namespace Consumer;

public static class Welcome
{
    // Uses Greeter.Greet but not Greeter.Twice, so only a change to Greet's signature reaches it.
    public static string For(string who) => Lib.Greeter.Greet(who);

    // Generated by Generator from Lib's public members.
    public static string LibMembers => GreeterMembers.Names;
#if NET10_0_OR_GREATER

    // Lib.Greeter.Shout exists only for net10.0, so only that build of Consumer uses it.
    public static string Loudly(string who) => Lib.Greeter.Shout(who);
#endif
}
